def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    best_candidate = -np.inf * np.ones(dim)
    best_fitness = float('inf')
    for i in range(budget):
        candidate = clip(rng.normal(size=dim))
        fitness = func(candidate)
        if fitness < best_fitness:
            best_candidate = candidate
            best_fitness = fitness

        # Gaussian perturbation around the current best candidate
        sigma = 1 / (i + 2) ** 0.5
        perturbed_candidate = clip(best_candidate + rng.normal(loc=best_candidate, scale=sigma))
        perturbed_fitness = func(perturbed_candidate)
        if perturbed_fitness < best_fitness:
            best_candidate = perturbed_candidate
            best_fitness = perturbed_fitness

    return best_candidate

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    x = np.random.uniform(lb, ub, size=dim)
    best_x = x.copy()
    best_f = func(x)

    for i in range(budget):
        t = 1 / (i + 1)  # adaptive temperature schedule
        step_size = rng.uniform(0.01, 0.05)  # random step size

        new_x = clip(best_x + rng.normal(size=dim) * step_size)
        new_f = func(new_x)

        if new_f < best_f:
            best_x = new_x
            best_f = new_f

        for _ in range(dim):
            j = np.random.randint(0, dim)
            new_x[j] += rng.uniform(-step_size, step_size)
            new_x = clip(new_x)
            new_f = func(new_x)

            if new_f < best_f:
                best_x = new_x
                best_f = new_f

    return best_x
